sys_script_client.script:
function onLoad() {
    //MSSFunds-1: Make Auto Choice options grayed out
    function disableOption(fieldName, choiceValue) {
        fieldName = g_form.removeCurrentPrefix(fieldName);
        var control = g_form.getControl(fieldName);
        if (control && !control.options) {
            var name = 'sys_select.' + this.tableName + '.' + fieldName;
            control = gel(name);
        }
        if (!control)
            return;
        if (!control.options)
            return;
        var options = control.options;
        for (var i = 0; i < options.length; i++) {
            var option = options[i];
            if (option.value == choiceValue) {
                control.options[i].disabled = 'true';
                break;
            }
        }
    }
    disableOption('recon_signoff_status', 'auto_singed_off');
    disableOption('recon_signoff_status', 'auto_signed_off_rejection');

}
